package local.lito381.server;
/** Original Source identity and exact target scan, without caster-id session recapture. */
final class NativeSourceCubeRelation {
 static NativeSourceCubeOrigin.Entity entity(Object cube){var e=CombatAccess.field(cube,"nativeSourceCubeEntity");return e instanceof NativeSourceCubeOrigin.Entity original?original:null;}
 static boolean scoped(NativeSourceCubeOrigin.Entity e){return CombatRules.loaded()&&e!=null&&e.scene()!=null;}
 /** Binding.source already stores ClientSession.sourceCharacterIdentity, not a server name. */
 static String identity(NativeSourceCubeOrigin.Creator creator){return creator==null||creator.binding()==null?null:creator.binding().source();}
 static String identity(Object cube){var e=entity(cube);return e==null?null:identity(e.creator());}
 static NativeSourceCubeOrigin.Scan scan(NativeSourceCubeOrigin.Entity e){var value=CombatAccess.field(e.engine(),"nativeSourceCubeScan");return value instanceof NativeSourceCubeOrigin.Scan s&&s.epoch()==e.epoch()?s:null;}
 static boolean sameCreator(NativeSourceCubeOrigin.Creator creator,NativeSourceCubeOrigin.Target target){return creator!=null&&target!=null&&target.kind()==0&&creator.pc()==target.pc()&&creator.binding()!=null&&creator.binding().equals(target.binding());}
 static boolean owner(NativeSourceCubeOrigin.Entity e){var s=e.scene();return Thread.holdsLock(s.hub())&&Thread.holdsLock(e.engine())&&NativeSourceCubePlayer.entityCurrent(e,NativePlayerLifetime.of(s.hub()))&&NativePlayerLifetime.of(s.hub()).admits()&&((BattleRules.MatchState)CombatAccess.field(s.room(),"match")).phase()==BattleRules.Phase.RUNNING;}
 static int compare(long actor,long caster,Object cube){var e=entity(cube);if(!scoped(e)||actor!=caster)return Long.compare(actor,caster);if(!owner(e))return 1;var s=scan(e);var t=s==null?null:s.targets().get(actor);return sameCreator(e.creator(),t)&&NativeSourceCubePlayer.targetCurrent(t,t.life(),e.scene())?0:1;}
 /** Existing match policy bounds new hostile installs; Source allies are still self/clan/party. */
 static int policy(boolean running,boolean self,boolean ally,boolean pvp,boolean team,int sourceForce,int targetForce,boolean sameId){if(!running)return -1;if(self||ally)return 0;if(!pvp||sameId)return -1;return !team||sourceForce>=0&&sourceForce<=1&&targetForce>=0&&targetForce<=1&&sourceForce!=targetForce?1:-1;}
 static boolean natural(NativeSourceCubeOrigin.Target t,NativeSourceCubeOrigin.Scene s){return NativeSourceCubeNpcLease.natural(t)&&CombatAccess.field(s.room(),t.kind()==1?"questEncounter":"timeAttackEncounter")==t.owner()&&CombatAccess.field(t.owner(),"sourceProcEncounterGeneration")==t.generation()&&NativeSourceArenaPoison.rawLife(t.actor())==t.life()&&(long)CombatAccess.field(t.actor(),"objectId")==t.id()&&(int)CombatAccess.field(t.actor(),"hp")>0;}
 /** -2 means original native fallback, -1 ignored, 0 Source ally, 1 Source enemy. */
 static int decision(Object cube,long caster,long id,Object actor){var e=entity(cube);if(!scoped(e))return -2;var kind=String.valueOf(CombatAccess.call(actor,"kind","()Llocal/lito381/server/"+e.engine().getClass().getSimpleName()+"$ActorKind;"));if(kind.equals("BOT"))return -2;var s=e.scene();if(!owner(e))return -1;var scan=scan(e);var t=scan==null?null:scan.targets().get(id);if(t==null||t.id()!=id)return -1;var match=(BattleRules.MatchState)CombatAccess.field(s.room(),"match");if(match.phase()!=BattleRules.Phase.RUNNING)return -1;
  if(t.kind()!=0)return natural(t,s)&&NativeSourceCubeNpc.factionAllowed(t.kind(),CombatAccess.field(cube,"nativeSourceCubeFaction"),t.kind()==1?(int)CombatAccess.field(t.actor(),"force"):-1)?1:-1;
  if(!NativeSourceCubePlayer.targetCurrent(t,t.life(),s)||NativeSourceDamageDisplay.n(t.pc(),"playerHp")<=0||e.creator()==null||e.creator().binding()==null||e.creator().binding().object()!=caster)return -1;var identity=identity(e.creator());if(identity==null)return -1;
  String target=t.binding().source();boolean self=sameCreator(e.creator(),t);boolean ally=self||s.hub().sameClan(identity,target)||s.hub().sameClassicParty(identity,target);var force=CombatAccess.field(cube,"nativeSourceCubeFaction");int sourceForce=force instanceof Integer i?i:-1;int targetForce=(int)CombatAccess.call(s.hub(),"forceOf","(Llocal/lito381/server/GameHub$Room;Llocal/lito381/server/ClientSession;)I",s.room(),t.pc());return policy(true,self,ally,match.rules().mode().playerVersusPlayer(),match.rules().teamBased(),sourceForce,targetForce,caster==id);
 }
 static BattleCubeIgnitionEffects.Relation relation(BattleCubeIgnitionEffects.Alliance original,long caster,long target,Object cube,Object actor){int d=decision(cube,caster,target,actor);return d==-2?original.relation(caster,target):d==0?BattleCubeIgnitionEffects.Relation.ALLY:d==1?BattleCubeIgnitionEffects.Relation.ENEMY:BattleCubeIgnitionEffects.Relation.IGNORE;}
 static BattleCubeQuakeEffects.Relation relation(BattleCubeQuakeEffects.Alliance original,long caster,long target,Object cube,Object actor){int d=decision(cube,caster,target,actor);return d==-2?original.relation(caster,target):d==0?BattleCubeQuakeEffects.Relation.ALLY:d==1?BattleCubeQuakeEffects.Relation.ENEMY:BattleCubeQuakeEffects.Relation.IGNORE;}
 static BattleCubeShockEffects.Relation relation(BattleCubeShockEffects.Alliance original,long caster,long target,Object cube,Object actor){int d=decision(cube,caster,target,actor);return d==-2?original.relation(caster,target):d==0?BattleCubeShockEffects.Relation.ALLY:d==1?BattleCubeShockEffects.Relation.ENEMY:BattleCubeShockEffects.Relation.IGNORE;}
 static BattleCubeHarmonyEffects.Relation relation(BattleCubeHarmonyEffects.Alliance original,long caster,long target,Object cube,Object actor){int d=decision(cube,caster,target,actor);return d==-2?original.relation(caster,target):d==0?BattleCubeHarmonyEffects.Relation.ALLY:d==1?BattleCubeHarmonyEffects.Relation.ENEMY:BattleCubeHarmonyEffects.Relation.IGNORE;}
 private NativeSourceCubeRelation(){}
}
